"use client";

import { useEffect, useState } from "react";
import { Play, Square, Terminal } from "lucide-react";
import { cn } from "@/lib/utils";
import { secondary } from "@/lib/takt-surface";

export type RunState = {
  phase: "idle" | "compile" | "run" | "done" | "error" | "stopped";
  output?: string;
  duration?: number;
};
const labels = {
  idle: "Ready to run",
  compile: "Compiling",
  run: "Running",
  done: "Finished",
  error: "Error",
  stopped: "Stopped",
};
export function RunConsole({
  state,
  onStop,
  onErrorLocation,
  className,
}: {
  state?: RunState;
  onStop?: () => void;
  onErrorLocation?: () => void;
  className?: string;
}) {
  const [demo, setDemo] = useState<RunState>({ phase: "idle" });
  const current = state ?? demo;
  const busy = current.phase === "compile" || current.phase === "run";
  useEffect(() => {
    if (state || (demo.phase !== "compile" && demo.phase !== "run")) return;
    const started = performance.now();
    const timer = setTimeout(
      () =>
        setDemo(
          demo.phase === "compile"
            ? { phase: "run" }
            : {
                phase: "done",
                output: 'match("UI-42") → true',
                duration: Math.round(performance.now() - started),
              },
        ),
      450,
    );
    return () => clearTimeout(timer);
  }, [state, demo.phase]);
  return (
    <section
      className={cn(
        "grid w-72 max-w-full gap-3 rounded-xl border bg-card p-4 text-card-foreground shadow-sm",
        className,
      )}
    >
      <header className="flex items-center gap-2 text-xs">
        <Terminal size={16} />
        <strong className="mr-auto">Console</strong>
        {current.duration !== undefined && (
          <span className="font-mono text-muted-foreground">
            {current.duration} ms
          </span>
        )}
      </header>
      <div
        role="status"
        className="grid min-h-16 content-start gap-2 rounded-lg bg-neutral-950 p-3 font-mono text-xs text-neutral-100 dark:border dark:border-white/10"
      >
        <span
          key={current.phase}
          className="flex items-center gap-2 motion-safe:animate-in motion-safe:fade-in"
        >
          <i
            aria-hidden
            className={cn(
              "size-1.5 rounded-full bg-current",
              busy && "motion-safe:animate-pulse",
            )}
          />
          {labels[current.phase]}
        </span>
        {current.output && (
          <pre className="max-h-28 overflow-auto whitespace-pre-wrap break-all border-t pt-2">
            {current.output}
          </pre>
        )}
      </div>
      {busy && (onStop || !state) ? (
        <button
          type="button"
          className={secondary}
          onClick={onStop ?? (() => setDemo({ phase: "stopped" }))}
        >
          <Square size={12} />
          Stop
        </button>
      ) : (
        !state && (
          <button
            type="button"
            className={secondary}
            onClick={() => setDemo({ phase: "compile" })}
          >
            <Play size={13} />
            Run sample
          </button>
        )
      )}
      {current.phase === "error" && onErrorLocation && (
        <button type="button" className={secondary} onClick={onErrorLocation}>
          Go to error
        </button>
      )}
    </section>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
